import type * as React from "react"
import { cn } from "cn"

/**
 * Document frame: the <html> root every page renders into. head, critical-css
 * and body are host nodes the publisher fills (metadata, inlined theme CSS,
 * the page's frame + sections). variant.status is the bare document for
 * status pages (404, 500, maintenance): body centered on the viewport.
 */
export default function Document({
  lang = "en",
  dir = "ltr",
  variant = "page",
  head,
  criticalCss,
  body,
  className,
}: {
  lang?: string
  dir?: "ltr" | "rtl"
  variant?: "page" | "status"
  head?: React.ReactNode
  criticalCss?: string
  body: React.ReactNode
  className?: string
}) {
  return (
    <html lang={lang} dir={dir} data-slot="document" data-variant={variant} suppressHydrationWarning>
      <head>
        <meta charSet="utf-8" />
        <meta name="viewport" content="width=device-width, initial-scale=1" />
        {criticalCss && <style data-slot="critical-css" dangerouslySetInnerHTML={{ __html: criticalCss }} />}
        {head}
      </head>
      <body
        className={cn(
          "min-h-svh bg-background font-sans text-foreground antialiased",
          variant === "status" && "grid place-items-center",
          className
        )}
      >
        {body}
      </body>
    </html>
  )
}
